import { Component, createEffect, createMemo, createSignal, For, JSX, Show, splitProps } from "solid-js";

import { getMajorLeader } from "#core/ui/utilities/diplomacy-utilities.js";
import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { CardFrame } from "#core/ui-next/components/card-frame.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { useImageCache } from "#core/ui-next/components/image-cache.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";

import { FramedResource } from "#base/ui-next/components/framed-resource.jsx";
import { LeaderWithRibbon } from "#base/ui-next/components/leader-with-ribbon.jsx";
import { CommerceCriteriaDisplay } from "#base/ui-next/screens/commerce/commerce-criteria-display.jsx";
import {
	TradeRouteAvailabiltyType,
	TradeRouteData,
	useCommerceScreenContext,
} from "#base/ui-next/screens/commerce/commerce-screen-model.js";
import { ResourceTooltip } from "#base/ui-next/tooltips/resource-tooltip.jsx";

interface TradeRouteCardProps extends JSX.HTMLAttributes<HTMLDivElement> {
	tradeRoute: TradeRouteData;
	autoFocus: boolean;
	disabled: boolean;
	onFocus?: () => void;
}
const TradeCardSymbol = Symbol();

export const TRADE_ROUTE_CARD_MARGIN_RIGHT = Layout.pixelsToScreenPixels(12);

const TradeRouteCardComponent: Component<TradeRouteCardProps> = (props) => {
	const [local, cardFrameProps] = splitProps(props, ["tradeRoute", "autoFocus", "class", "onFocus"]);
	const model = useCommerceScreenContext();
	const [majorLeaderId, setMajorLeaderId] = createSignal<PlayerId>(PlayerIds.NO_PLAYER);
	const isSelected = createMemo(() =>
		ComponentID.isMatch(model.selectedTradeRouteId() ?? null, props.tradeRoute.cityID),
	);
	const autoFocusFirstItem = createMemo(() => {
		return isSelected();
	});

	createEffect(() => {
		const majorLeader = getMajorLeader(local.tradeRoute.leaderId);
		if (!majorLeader) {
			return;
		}
		setMajorLeaderId(majorLeader.id);
	});

	const images = {
		ticketSelectedCSS: "url(blp:base_ticket-select-bg)",
	};

	const imageCache = useImageCache();
	imageCache.registerImages(TradeCardSymbol, Object.values(images));

	const content = (
		<CardFrame
			{...cardFrameProps}
			class={`px-4 pt-4 pb-2 flex flex-col mb-2 mt-2 relative focusable-card ${local.class ?? ""}`}
			classList={{ disabled: local.tradeRoute.availability === TradeRouteAvailabiltyType.Unavailable }}
		>
			<Activatable
				disableFocus={true}
				onActivate={() => {
					model.clickCityName(local.tradeRoute.cityID);
				}}
			>
				<div class="flex flex-row text-secondary uppercase text-lg mb-1 items-center">
					<div
						class="flex flex-row mr-3 items-center justify-center size-9 bg-center bg-cover bg-no-repeat"
						style={{ "background-image": `url("blp:banner_hex")` }}
					>
						<Icon
							class="size-8"
							name={local.tradeRoute.cityIcon}
						/>
					</div>
					<div class="font-title">
						<L10n.Compose text={local.tradeRoute.cityName} />
					</div>
				</div>
			</Activatable>
			<p class="mt-1 mr-13 font-fit-shrink">{local.tradeRoute.domainString}</p>
			<div class="flex flex-row flex-wrap mt-4 mr-13">
				<For each={local.tradeRoute.incomingResources}>
					{(resource, index) => (
						<ResourceTooltip {...resource}>
							{(() => {
								const [focused, setFocused] = createSignal(false);
								return (
									<Activatable
										// require explicit size and mb in the parent because flex-wrap things can get unhappy otherwise
										class="size-13 mb-4 pointer-events-auto mr-2 hover\:scale-125 focus\:scale-125"
										classList={{ "focused-resource": focused() }}
										onFocus={() => setFocused(true)}
										onBlur={() => setFocused(false)}
										disabled={!isSelected()}
										autoFocus={index() === 0 && autoFocusFirstItem()}
										suppressPointerChanges
									>
										<FramedResource
											size={13}
											{...resource}
										/>
									</Activatable>
								);
							})()}
						</ResourceTooltip>
					)}
				</For>
			</div>
			<div class="mt-2">{local.tradeRoute.yieldElement}</div>
			<Show when={majorLeaderId() !== PlayerIds.NO_PLAYER}>
				<div class="absolute top-1 right-1 flex flex-col items-center">
					<LeaderWithRibbon
						{...{
							leaderId: majorLeaderId(),
							size: 20,
							representsCityState: local.tradeRoute.isCityState,
							cityId: local.tradeRoute.cityID,
						}}
					/>
					<Show when={!local.tradeRoute.isCityState}>
						<div
							class="size-12 mt-2 flex flex-row text-sm items-center justify-center bg-center bg-contain bg-no-repeat text-white -mt-3"
							style={{ "background-image": `url("blp:relationships_normal-tab-button")` }}
						>
							{"+" + local.tradeRoute.relationshipChange}
						</div>
					</Show>
				</div>
			</Show>
			<Show when={local.tradeRoute.availability === TradeRouteAvailabiltyType.Unavailable}>
				<div
					class="mt-2 p-2 flex flex-col justify-between"
					style={{ "background-color": "rgba(0,0,0, 0.4)" }}
				>
					<For each={local.tradeRoute.statuses}>
						{(status) => <CommerceCriteriaDisplay status={status} />}
					</For>
				</div>
			</Show>
		</CardFrame>
	);

	return (
		<Activatable
			name={`${Locale.compose(local.tradeRoute.cityName)}-Trade-Route-Card`}
			class="focusable-card-activatable trade-route-card"
			autoFocus={local.autoFocus}
			onActivate={() => model.setSelectedTradeRouteId(props.tradeRoute.cityID)}
			disabled={!IsControllerActive() || props.disabled || model.selectedTradeRouteId() !== undefined}
			onFocus={local.onFocus}
			suppressPointerChanges
		>
			{content}
		</Activatable>
	);
};

export const TradeRouteCard = ComponentRegistry.register({
	name: "TradeRouteCard",
	createInstance: TradeRouteCardComponent,
});
